1: <div class="job-status-panel boxed-section {{if this.isActivelyDeploying "active-deployment is-info"}}" data-test-job-status-panel data-test-status-mode={{@statusMode}}>
2:   <div class="boxed-section-head">
3:     {{#if this.isActivelyDeploying}}
4:       <div class="boxed-section-row">
5:         Deployment Status
6:         <span class="badge is-white bumper-left" data-test-active-deployment-stat="id">{{@job.latestDeployment.shortId}}</span>
7:         <div class="pull-right">
8:           {{#if @job.latestDeployment.isRunning}}
9:             <TwoStepButton
10:               data-test-fail
11:               @classes={{hash
12:                 idleButton="is-danger"
13:                 confirmationMessage="inherit-color"
14:                 confirmButton="is-danger"}}
15:               @idleText="Fail Deployment"
16:               @cancelText="Cancel"
17:               @confirmText="Yes, Fail Deployment"
18:               @confirmationMessage="Are you sure?"
19:               @inlineText={{true}}
20:               @awaitingConfirmation={{this.fail.isRunning}}
21:               @disabled={{this.fail.isRunning}}
22:               @onConfirm={{perform this.fail}} />
23:           {{/if}}
24:           {{#if @job.latestDeployment.requiresPromotion}}
25:             <button
26:               data-test-promote-canary
27:               type="button"
28:               class="button is-warning is-small {{if this.promote.isRunning "is-loading"}}"
29:               disabled={{this.promote.isRunning}}
30:               onclick={{perform this.promote}}>Promote Canary</button>
31:           {{/if}}
32:         </div>
33:       </div>
34:     {{else}}

